import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def solve_search(limit):
    primes_q = []
    is_prime_list = [True] * (limit + 1)
    is_prime_list[0] = is_prime_list[1] = False
    for p in range(2, limit + 1):
        if is_prime_list[p]:
            primes_q.append(p)
            for multiple in range(p * p, limit + 1, p):
                is_prime_list[multiple] = False

    solutions = []
    print(f"Starting search for primes q up to {limit}...")

    for q in primes_q:
        N = q**2 - q + 1

        # Check if N is a perfect cube k^3
        # Estimate k
        k_float = N**(1/3)
        k_round = int(round(k_float))

        # Check if k_round is the exact cube root
        if k_round**3 == N:
            k = k_round

            # Verification checks
            if k != q and is_prime(k):
                # q is prime by construction, k is prime, k != q
                solutions.append((q, k))

    return solutions

# Run the search up to 1000
results = solve_search(1000)
print("Found solutions (q, k):")
print(results)
